// Wired-anywhere index — record JAH-GGN-POWERLINEADAPTER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"speed_mbps": 2000, "price_usd": 90};
var value = (m.speed_mbps/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-POWERLINEADAPTER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-POWERLINEADAPTER-000001|' + value.toFixed(2) + ' wired index');

